from collections import Counter

def minimumIncompatibility(nums: list[int], k: int) -> int:
    from functools import lru_cache
    n = len(nums)
    size = n // k
    # Every number cannot appear more than k times
    if any(v > k for v in Counter(nums).values()):
        return -1

    # Precompute all valid subsets as bitmasks
    valid = []
    for mask in range(1 << n):
        if bin(mask).count('1') == size:
            seen = set()
            vals = []
            for i in range(n):
                if (mask >> i) & 1:
                    if nums[i] in seen:
                        break
                    seen.add(nums[i])
                    vals.append(nums[i])
            else:
                valid.append((mask, max(vals) - min(vals)))

    @lru_cache(maxsize=None)
    def dp(used):
        if used == (1 << n) - 1:
            return 0
        ans = float('inf')
        low = ~used & (used + 1)  # lowest unused element must go in the next subset
        for mask, cost in valid:
            if mask & low and mask & used == 0:
                res = dp(used | mask)
                if res != float('inf'):
                    ans = min(ans, cost + res)
        return ans

    ans = dp(0)
    return ans if ans < float('inf') else -1
